key_concepts.raw_code_snippet:
# In số thứ tự từ 0 đến 4 cho 5 sản phẩm
for item_index in range(5):
    print("Sản phẩm số:", item_index)

# Lặp các số lẻ từ 1 đến 9 đại diện cho các quầy thanh toán đang mở
for counter_number in range(1, 10, 2):
    print("Quầy đang hoạt động:", counter_number)

gotchas_and_errors.code_bad:
# Muốn in số thứ tự từ 1 đến 5 nhưng viết sai range(1, 5)
for item_id in range(1, 5):
    print("Mặt hàng số:", item_id)  # Chỉ in đến 4

gotchas_and_errors.code_good:
# Khắc phục: Tăng giá trị stop lên 1 đơn vị hoặc ghi 5 + 1
for item_id in range(1, 5 + 1):
    print("Mặt hàng số:", item_id)  # In đủ từ 1 đến 5

gotchas_and_errors.code_bad:
# Muốn đếm ngược từ 5 về 1 nhưng không truyền step = -1
for countdown in range(5, 1):
    print("Đếm ngược:", countdown)  # Khối lệnh này sẽ KHÔNG bao giờ chạy

gotchas_and_errors.code_good:
# Khắc phục: Thêm tham số step âm (-1) để đếm lùi đúng cách
for countdown in range(5, 0, -1):
    print("Đếm ngược:", countdown)  # Chạy đúng từ 5 về 1
